#[must_use]
pub fn specification_to_domain(record: jig_client_protocol_wire::v44::Specification) -> jig_domain_people::Spec {
    let jig_client_protocol_wire::v44::Specification { words: field_000000, parameters: field_000001, inputs: field_000002, asks: field_000003 } = record;
    jig_domain_people::Spec {
        words: field_000000,
        parameters: {
            let source = field_000001;
            let count = source.len();
            let mut translated = skein_lib::List::with_capacity(count);
            for item in source.into_boxed() {
                let converted = parameter_to_domain(item);
                assert!(translated.push(converted).is_ok(), "one output per source item");
            }
            Box::from(translated)
        },
        inputs: {
            let source = field_000002;
            let count = source.len();
            let mut translated = skein_lib::List::with_capacity(count);
            for item in source.into_boxed() {
                let converted = item;
                assert!(translated.push(converted).is_ok(), "one output per source item");
            }
            Box::from(translated)
        },
        asks: field_000003
    }
}

