pub fn pattern_to_record(value: &jig_domain_tasks::Pattern) -> Result<jig_client_protocol_wire::v44::Pattern, jig_client_protocol_wire::v44::Problem> {
    let jig_domain_tasks::Pattern { segments: field_000000, last: field_000001 } = value;
    Ok(jig_client_protocol_wire::v44::Pattern {
        segments: {
            let source = field_000000;
            let count = match u32::try_from(source.len()) { Ok(count) => count, Err(_error) => return Err(jig_client_protocol_wire::v44::paths::PATTERN_SEGMENTS.problem(skein_codec::Reason::Bound)) };
            let mut translated = skein_lib::List::with_capacity(count);
            for item in source.as_ref() {
                let converted = item.clone();
                assert!(translated.push(converted).is_ok(), "one output per source item");
            }
            translated
        },
        last: pattern_end_to_record(field_000001)
    })
}

